import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

const Etudiants = () => {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        setLoading(true);
        setError("");
        const token = localStorage.getItem("token");
        
        console.log("🔍 Récupération des étudiants...");
        console.log("🔐 Token:", token ? "Présent" : "Manquant");

        const response = await fetch("http://localhost:5000/api/students", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        console.log("📡 Statut réponse:", response.status);
        
        const data = await response.json();
        console.log("📊 Données reçues:", data);

        if (response.ok && data.success) {
          setStudents(data.students || []);
          console.log(`✅ ${data.students?.length || 0} étudiants chargés`);
        } else {
          setError(data.message || "Erreur lors du chargement des étudiants");
          setStudents([]);
        }
      } catch (error) {
        console.error("❌ Erreur fetch étudiants:", error);
        setError("Erreur de connexion au serveur");
        setStudents([]);
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  const handleCreateStudent = () => {
    navigate("/creer-student");
  };

  const handleRefresh = () => {
    window.location.reload();
  };

  if (loading) {
    return (
      <div style={{ padding: "2rem", textAlign: "center" }}>
        <div style={{ 
          display: "inline-block", 
          padding: "1rem 2rem", 
          background: "#f8fafc", 
          borderRadius: "8px",
          border: "1px solid #e2e8f0"
        }}>
          ⏳ Chargement des étudiants...
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: "2rem", maxWidth: "1200px", margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "2rem" }}>
        <h1 style={{ color: "#2d3748", margin: 0 }}>👨‍🎓 Liste des Étudiants</h1>
        <div style={{ display: "flex", gap: "1rem" }}>
          <button 
            onClick={handleRefresh}
            style={{ 
              padding: "0.6rem 1.2rem", 
              borderRadius: "8px", 
              background: "#f1f5f9", 
              color: "#475569", 
              border: "1px solid #e2e8f0", 
              cursor: "pointer",
              fontWeight: "500"
            }}
          >
            🔄 Actualiser
          </button>
          <button 
            onClick={handleCreateStudent} 
            style={{ 
              padding: "0.6rem 1.2rem", 
              borderRadius: "8px", 
              background: "#2563eb", 
              color: "white", 
              border: "none", 
              cursor: "pointer",
              fontWeight: "500",
              display: "flex",
              alignItems: "center",
              gap: "0.5rem"
            }}
          >
            ➕ Créer un nouvel étudiant
          </button>
        </div>
      </div>

      {error && (
        <div style={{
          padding: "1rem",
          backgroundColor: "#fed7d7",
          color: "#c53030",
          borderRadius: "8px",
          marginBottom: "1.5rem",
          border: "1px solid #feb2b2",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center"
        }}>
          <span>❌ {error}</span>
          <button 
            onClick={() => setError("")}
            style={{ 
              background: "none", 
              border: "none", 
              color: "#c53030", 
              cursor: "pointer",
              fontSize: "1.2rem"
            }}
          >
            ×
          </button>
        </div>
      )}

      {students.length === 0 ? (
        <div style={{ 
          textAlign: "center", 
          padding: "3rem", 
          background: "#f8fafc", 
          borderRadius: "12px",
          border: "2px dashed #e2e8f0"
        }}>
          <div style={{ fontSize: "3rem", marginBottom: "1rem" }}>👨‍🎓</div>
          <h3 style={{ color: "#64748b", marginBottom: "0.5rem" }}>Aucun étudiant trouvé</h3>
          <p style={{ color: "#94a3b8", marginBottom: "1.5rem" }}>
            {error ? "Erreur lors du chargement" : "Aucun étudiant inscrit pour le moment"}
          </p>
          <button 
            onClick={handleCreateStudent}
            style={{ 
              padding: "0.75rem 1.5rem", 
              borderRadius: "8px", 
              background: "#2563eb", 
              color: "white", 
              border: "none", 
              cursor: "pointer",
              fontWeight: "500"
            }}
          >
            ➕ Ajouter le premier étudiant
          </button>
        </div>
      ) : (
        <div style={{ 
          background: "white", 
          borderRadius: "12px", 
          overflow: "hidden",
          boxShadow: "0 4px 6px rgba(0, 0, 0, 0.05)",
          border: "1px solid #e2e8f0"
        }}>
          <div style={{ 
            padding: "1rem 1.5rem", 
            background: "#f8fafc", 
            borderBottom: "1px solid #e2e8f0",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}>
            <span style={{ fontWeight: "600", color: "#475569" }}>
              📊 {students.length} étudiant{students.length > 1 ? 's' : ''} au total
            </span>
            <span style={{ color: "#64748b", fontSize: "0.875rem" }}>
              Dernière mise à jour: {new Date().toLocaleTimeString()}
            </span>
          </div>
          
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={thStyle}>ID</th>
                <th style={thStyle}>Nom</th>
                <th style={thStyle}>Email</th>
                <th style={thStyle}>Classe</th>
                <th style={thStyle}>Niveau</th>
                <th style={thStyle}>Date d'inscription</th>
              </tr>
            </thead>
            <tbody>
              {students.map((student, index) => (
                <tr key={student.id} style={{ 
                  backgroundColor: index % 2 === 0 ? '#ffffff' : '#f8fafc',
                  transition: 'background-color 0.2s'
                }}>
                  <td style={tdStyle}>
                    <span style={{ 
                      background: "#f1f5f9", 
                      padding: "0.25rem 0.5rem", 
                      borderRadius: "4px", 
                      fontSize: "0.875rem",
                      fontWeight: "600",
                      color: "#475569"
                    }}>
                      #{student.id}
                    </span>
                  </td>
                  <td style={tdStyle}>
                    <div style={{ fontWeight: "600", color: "#1e293b" }}>
                      {student.nom}
                    </div>
                  </td>
                  <td style={tdStyle}>
                    <div style={{ color: "#475569" }}>{student.email}</div>
                  </td>
                  <td style={tdStyle}>
                    <span style={{ 
                      background: student.class_name ? "#dbeafe" : "#f1f5f9", 
                      color: student.class_name ? "#1e40af" : "#64748b",
                      padding: "0.25rem 0.75rem", 
                      borderRadius: "20px", 
                      fontSize: "0.875rem",
                      fontWeight: "500"
                    }}>
                      {student.class_name || "Non attribuée"}
                    </span>
                  </td>
                  <td style={tdStyle}>
                    <span style={{ 
                      color: "#475569",
                      fontSize: "0.875rem"
                    }}>
                      {student.class_niveau || "-"}
                    </span>
                  </td>
                  <td style={tdStyle}>
                    <span style={{ 
                      color: "#64748b",
                      fontSize: "0.875rem"
                    }}>
                      {student.created_at ? new Date(student.created_at).toLocaleDateString('fr-FR') : "-"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

const thStyle = { 
  borderBottom: "1px solid #e2e8f0", 
  padding: "1rem", 
  textAlign: "left", 
  background: "#f8fafc",
  fontWeight: "600",
  color: "#374151",
  fontSize: "0.875rem",
  textTransform: "uppercase",
  letterSpacing: "0.05em"
};

const tdStyle = { 
  borderBottom: "1px solid #f1f5f9", 
  padding: "1rem",
  fontSize: "0.875rem"
};

export default Etudiants;
